// src/App.js — một nguồn sự thật (AuthProvider), đọc qua useAuth có chốt kiểm
import { createContext, useContext, useState } from 'react';

const AuthContext = createContext(null);

function AuthProvider({ children }) {
  const [user, setUser] = useState(null);
  const login = (name) => setUser({ name });
  const logout = () => setUser(null);
  return <AuthContext.Provider value={{ user, login, logout }}>{children}</AuthContext.Provider>;
}

export function useAuth() {
  const ctx = useContext(AuthContext);
  if (!ctx) throw new Error('useAuth must be used inside AuthProvider');
  return ctx;
}

function Navbar() {
  const { user, logout } = useAuth();
  return (
    <nav>
      <span id="greeting">{user ? `Hello, ${user.name}` : 'Guest'}</span>
      {user && <button id="btn-logout" type="button" onClick={logout}>Logout</button>}
    </nav>
  );
}

function LoginPanel() {
  const { user, login } = useAuth();
  const [name, setName] = useState('');
  if (user) return null;
  const submit = () => {
    if (name.trim()) login(name.trim());
  };
  return (
    <div id="login-panel">
      <input id="name" value={name} onChange={(e) => setName(e.target.value)} />
      <button id="btn-login" type="button" onClick={submit}>Login</button>
    </div>
  );
}

export default function App() {
  return (
    <AuthProvider>
      <Navbar />
      <LoginPanel />
    </AuthProvider>
  );
}

